import itertools, random
from renewal_orig import process_renewal as orig
from renewal import process_renewal as new

def gen():
    cases=[]
    # malformed
    cases += [(None,None),(42,{}),({},{}),({},None),([],{}),("x","y")]
    # missing fields
    base={"id":"a","status":"active","tier":"basic"}
    pay={"amount":40,"method":"card"}
    for k in ["id","status","tier"]:
        m=dict(base); del m[k]; cases.append((m,dict(pay)))
    for k in ["amount","method"]:
        p=dict(pay); del p[k]; cases.append((dict(base),p))
    # bad id
    for i in [None,42,"",1.5,[],{}]:
        m=dict(base); m["id"]=i; cases.append((m,dict(pay)))
    # tiers
    for tier in ["basic","gold","platinum",None,42,""]:
        for status in ["active","lapsed","suspended"]:
            m={"id":"a","status":status,"tier":tier}
            if status=="lapsed": m["expired_days"]=5
            if status=="suspended": m["strikes"]=0
            cases.append((m,dict(pay)))
    # amounts
    for amt in [0,-1,40,39,41,90,89,91,100,"40",None,1.5]:
        for method in ["card","transfer","cash",None,42,""]:
            for status in ["active","lapsed","suspended"]:
                m={"id":"a","status":status,"tier":"gold"}
                if status=="lapsed": m["expired_days"]=0
                if status=="suspended": m["strikes"]=2
                cases.append((m,{"amount":amt,"method":method}))
    # lapsed expiry
    for ed in [0,29,30,31,100,-1,None,"5",1.5]:
        for tier in ["basic","gold"]:
            m={"id":"a","status":"lapsed","tier":tier,"expired_days":ed}
            cases.append((m,dict(pay)))
    # suspended strikes
    for st in [0,1,2,3,4,-1,None,"2",1.5]:
        for tier in ["basic","gold"]:
            m={"id":"a","status":"suspended","tier":tier,"strikes":st}
            cases.append((m,{"amount":100,"method":"card"}))
    # banned / unknown
    cases.append(({"id":"a","status":"banned","tier":"basic"},dict(pay)))
    cases.append(({"id":"a","status":"weird","tier":"basic"},dict(pay)))
    # method receipt check with exact amounts
    for method in ["card","transfer"]:
        m={"id":"x1","status":"active","tier":"gold"}
        cases.append((m,{"amount":90,"method":method}))
    return cases

cases=gen()
bad=0
for i,(m,p) in enumerate(cases):
    a=orig(m,p); b=new(m,p)
    if a!=b:
        bad+=1
        print("DIFF",i,repr(m),repr(p),"orig=",a,"new=",b)
print("total",len(cases),"diffs",bad)
EOF
echo ok

