# Per-status job: the extra field to validate and the status/charge scheme.
# The fee and outcome status are derived per status, then the shared payment
# checks and receipt building run once.
STATUS_PLAN = {
    "active": {"field": None, "kind": "plain", "outcome": "renewed"},
    "lapsed": {"field": "expired_days", "kind": "grace", "outcome": None},
    "suspended": {"field": "strikes", "kind": "surcharge", "outcome": "reactivated"},
}


def _bad_field(member, field: str, ceil: bool = False) -> bool:
    """True when a status-specific integer field is missing or malformed."""
    value = member.get(field)
    if not isinstance(value, int) or value < 0:
        return True
    return value >= MAX_STRIKES if ceil else False


def _plan(status: str) -> dict | None:
    return STATUS_PLAN.get(status)


